async function main() {
  const repoUrl = 'git@github.com:zelarhq/nodejs-welcome.git';
  const repoDir = 'nodejs-welcome';

  // 1. Clone the repo
  console.log(`Cloning repository from ${repoUrl} into ${repoDir}...`);
  await tools.clone_repo({ repo_url: repoUrl, destination: repoDir });
  console.log('Repository cloned successfully.');

  // 2. Analyse the contents of the repo
  console.log(`Analyzing contents of ${repoDir}...`);
  await tools.analyse_repo_contents({ directory_name: repoDir });
  console.log('Repository analysis complete.');

  // 2.1 Create/update Dockerfile based on the analysis.
  console.log('Generating Dockerfile...');
  await tools.create_a_docker_file({ directory_name: repoDir });
  console.log('Dockerfile generated successfully.');

  // 2.2 Kubernetes yamls based on the analysis.
  console.log('Generating Kubernetes YAML files...');
  // Assuming the analysis provides enough info, we use the directory name for naming.
  await tools.create_kubernetes_yaml_file({ directory_name: repoDir });
  console.log('Kubernetes YAML files generated successfully.');

  // 3. Add all changed files to git changes
  console.log('Staging all changes...');
  // This step is implicitly handled by push_git_changes_to_github which calls git add all changes.
  // We will proceed to push, which includes the add step.

  // 4. Commit / push to repo
  const commitMessage = 'Automated update: Added Dockerfile and Kubernetes manifests';
  console.log(`Committing and pushing changes to ${repoDir} with message: "${commitMessage}"`);
  await tools.push_git_changes_to_github({
    directory_name: repoDir,
    commit_message: commitMessage,
    branch_name: 'main' // Assuming 'main' is the target branch
  });
  console.log('Changes pushed successfully!');
}

main().catch(err => {
  console.error('An error occurred during the process:', err);
});

